// 逐位搬移：取出 n 的最低位，放到結果的最低位後左移
// 時間複雜度: O(32)，空間複雜度: O(1)
function reverseBits(n) {
    let result = 0;
    for (let i = 0; i < 32; i++) {
        result = (result << 1) | (n & 1);
        n >>>= 1; // 無號右移
    }
    return result >>> 0; // 轉回無號 32 位元
}

